(() => {
  const canvas = document.querySelector('[data-mosaic-background]');
  if (!canvas) return;
  const mosaic = new MosaicBackground(canvas, { data: window.MOSAIC_DATA, tileSize: 16 });
  const button = document.querySelector('[data-mosaic-pause]');
  if (button && mosaic.ctx) {
    button.hidden = false;
    button.addEventListener('click', () => {
      const paused = mosaic.togglePause();
      button.setAttribute('aria-pressed', String(paused));
      button.textContent = paused ? 'Resume background' : 'Pause background';
    });
  }
  window.mosaic = mosaic;
})();
